# Problem 1
# Variables: support dict block -> support (None means table), held block.
# Constraints: legal Blocksworld actions, goal, and if block1 is moved then
# block2 must be moved within the next two actions.
def name(b):
    return "block" + str(b).lower()

blocks = tuple(str(i) for i in range(1, 12))

initial = {b: None for b in blocks}
initial["3"] = "9"
initial["4"] = "11"
initial["8"] = "2"
initial["7"] = "8"

goal = {b: None for b in blocks}
goal["2"] = "4"
goal["3"] = "2"
goal["5"] = "3"
goal["8"] = "10"
goal["11"] = "8"
goal["7"] = "9"


def clear(b, on):
    return all(on[x] != b for x in on)


def generate():
    on = dict(initial)
    actions = []

    # First move every block that is on another block down to the table.
    while True:
        candidates = [b for b in blocks if on.get(b) is not None and clear(b, on)]
        if not candidates:
            break
        b = sorted(candidates)[0]
        c = on[b]
        actions.append(("unstack", (b, c)))
        on[b] = None
        actions.append(("putdown", (b,)))

    # Then build the goal towers from table-supported bottom blocks upward.
    children = {b: [] for b in blocks}
    bottoms = []
    for b in blocks:
        s = goal.get(b)
        if s is None:
            bottoms.append(b)
        else:
            children[s].append(b)

    for s in children:
        children[s].sort()
    bottoms.sort()

    for bottom in bottoms:
        cur = bottom
        while True:
            kids = children[cur]
            if not kids:
                break
            nxt = kids[0]
            actions.append(("pickup", (nxt,)))
            actions.append(("stack", (nxt, cur)))
            cur = nxt

    return actions


def validate(actions):
    on = dict(initial)
    held = None
    obligations = []

    for act, args in actions:
        if act == "pickup":
            b = args[0]
            if held is not None or on.get(b) is not None or not clear(b, on):
                return False
            on[b] = None
            held = b
        elif act == "unstack":
            b, c = args
            if held is not None or on.get(b) != c or not clear(b, on):
                return False
            on[b] = None
            held = b
        elif act == "putdown":
            b = args[0]
            if held != b:
                return False
            on[b] = None
            held = None
        elif act == "stack":
            b, c = args
            if held != b or c == b or c == held or not clear(c, on):
                return False
            on[b] = c
            held = None
        else:
            return False

        moved = args[0]
        next_obligations = []
        for target, remaining in obligations:
            if moved == target:
                continue
            remaining -= 1
            if remaining <= 0:
                return False
            next_obligations.append((target, remaining))

        if moved == "1":
            next_obligations.append(("2", 2))
        obligations = next_obligations

    if obligations:
        return False
    return held is None and all(on.get(b) == goal.get(b) for b in blocks)


actions = generate()
if validate(actions):
    for act, args in actions:
        if len(args) == 1:
            print(f"({act} {name(args[0])})")
        else:
            print(f"({act} {name(args[0])} {name(args[1])})")
else:
    print("No plan")

