# Problem 1
import heapq

N = 10

# state[i] = support of block i, 0 means table
initial = [0] * (N + 1)
goal = [0] * (N + 1)

goal[10] = 1
goal[8] = 4
goal[9] = 3
goal[2] = 9
goal[6] = 5
goal[7] = 6

# Additional constraint:
# if the previous high-level move was block2, next must be block4
# if the previous high-level move was block4, next must be block6
constraint = {2: 4, 4: 6}


def solve(allow_noop):
    init_state = tuple(initial)
    goal_state = tuple(goal)
    h_cache = {}

    def h(state):
        if state in h_cache:
            return h_cache[state]

        lower = [0] * (N + 1)

        for i in range(1, N + 1):
            if state[i] != goal[i]:
                lower[i] = 1

        changed = True
        while changed:
            changed = False
            for i in range(1, N + 1):
                s = state[i]
                g = goal[i]
                if s == g:
                    if s != 0 and lower[s] > 0:
                        val = 2
                    else:
                        val = 0
                else:
                    val = 1

                if val > lower[i]:
                    lower[i] = val
                    changed = True

        res = sum(lower[1:])
        h_cache[state] = res
        return res

    def successors(state, last):
        on_top = [False] * (N + 1)
        for i in range(1, N + 1):
            s = state[i]
            if s:
                on_top[s] = True

        clear = [i for i in range(1, N + 1) if not on_top[i]]
        required = constraint.get(last)

        for x in clear:
            if required is not None and x != required:
                continue

            sx = state[x]

            if allow_noop:
                yield state, x, sx, sx

            if sx != 0:
                ns = list(state)
                ns[x] = 0
                yield tuple(ns), x, sx, 0

            for y in clear:
                if y == x or y == sx:
                    continue
                ns = list(state)
                ns[x] = y
                yield tuple(ns), x, sx, y

    if init_state == goal_state and 0 not in constraint:
        return []

    start_h = h(init_state)
    heap = [(start_h, start_h, 0, init_state, 0)]
    best = {(init_state, 0): 0}
    parent = {}
    INF = 10 ** 9

    while heap:
        _, hval, g, state, last = heapq.heappop(heap)

        if g != best.get((state, last)):
            continue

        if state == goal_state and last not in constraint:
            cur = (state, last)
            moves = []

            while cur in parent:
                prev, x = parent[cur]
                dest = cur[0][x]
                source = prev[0][x]
                moves.append((x, source, dest))
                cur = prev

            moves.reverse()
            return moves

        for ns, x, sx, dest in successors(state, last):
            ng = g + 1
            key = (ns, x)

            if ng < best.get(key, INF):
                best[key] = ng
                parent[key] = ((state, last), x)
                nh = h(ns)
                heapq.heappush(heap, (ng + nh, nh, ng, ns, x))

    return None


def print_plan(moves):
    if moves is None:
        print("No plan")
        return

    for x, source, dest in moves:
        if source == 0:
            print(f"(pickup block{x})")
        else:
            print(f"(unstack block{x} block{source})")

        if dest == 0:
            print(f"(putdown block{x})")
        else:
            print(f"(stack block{x} block{dest})")


plan = solve(False)
if plan is None:
    plan = solve(True)

print_plan(plan)

