def move(state, x, dest, actions):
    src = state[x]
    if src == dest:
        return

    if src == 0:
        actions.append(("pickup", x))
    else:
        actions.append(("unstack", x, src))

    if dest == 0:
        actions.append(("putdown", x))
    else:
        actions.append(("stack", x, dest))

    state[x] = dest


