else:
    constructive = constructive_plan(initial_state)
    final = simulate_plan(constructive, initial_state)
    constructive_valid = final is not None and is_goal_state(final)
    upper_bound = len(constructive) if constructive_valid else None

    improved = astar_improve(initial_state, upper_bound)
