from collections import deque

blocks = list(range(1, 11))

initial_support = {b: None for b in blocks}
initial_support[4] = 8
initial_support[1] = 4
initial_support[2] = 1
initial_support[6] = 3
initial_support[10] = 5

goal_support = {b: None for b in blocks}

REQUIRED_STACKS = 10


def make_above(support):
    above = {b: None for b in blocks}
    for b, s in support.items():
        if s is not None:
            above[s] = b
    return above


def encode(support, arm):
    support = dict(support)
    if arm is not None:
        support[arm] = None
    above = make_above(support)
    return (
        tuple(support[b] for b in blocks),
        tuple(above[b] for b in blocks),
        arm,
    )


def decode(state):
    support = {b: state[0][i] for i, b in enumerate(blocks)}
    above = {b: state[1][i] for i, b in enumerate(blocks)}
    return support, above, state[2]


def stack_count(state):
    support, above, arm = decode(state)
    return sum(1 for b in blocks if support[b] is None and b != arm)


def apply_action(state, action):
    support, above, arm = decode(state)
    kind = action[0]

    if kind == 'pickup':
        b = action[1]
        if arm is not None or b == arm or support[b] is not None or above[b] is not None:
            return None
        support[b] = None
        arm = b

    elif kind == 'putdown':
        b = action[1]
        if arm != b:
            return None
        support[b] = None
        arm = None

    elif kind == 'unstack':
        b, s = action[1], action[2]
        if arm is not None or support[b] != s or above[b] is not None:
            return None
        support[b] = None
        above[s] = None
        arm = b

    elif kind == 'stack':
        b, s = action[1], action[2]
        if arm != b or b == s or above[s] is not None or s == arm:
            return None
        support[b] = s
        above[s] = b
        arm = None

    else:
        return None

    return encode(support, arm)


def neighbors(state):
    support, above, arm = decode(state)
    result = []

    if arm is None:
        for b in blocks:
            if support[b] is None and above[b] is None:
                result.append(('pickup', b))
            if support[b] is not None and above[b] is None:
                result.append(('unstack', b, support[b]))
    else:
        b = arm
        result.append(('putdown', b))
        for y in blocks:
            if y != b and above[y] is None:
                result.append(('stack', b, y))

    return result


def main():
    initial = encode(initial_support, None)
    goal = encode(goal_support, None)

    def ok(state):
        return stack_count(state) == REQUIRED_STACKS

    plan = None
    visited = set()
    queue = deque()

    for action in neighbors(initial):
        ns = apply_action(initial, action)
        if ns is None or not ok(ns) or ns in visited:
            continue
        visited.add(ns)
        if ns == goal:
            plan = [action]
            break
        queue.append((ns, [action]))

    if plan is None:
        while queue:
            state, plan_so_far = queue.popleft()
            for action in neighbors(state):
                ns = apply_action(state, action)
                if ns is None or not ok(ns) or ns in visited:
                    continue
                visited.add(ns)
                if ns == goal:
                    plan = plan_so_far + [action]
                    break
                queue.append((ns, plan_so_far + [action]))
            if plan is not None:
                break

    if plan is None:
        print("No plan")
    else:
        for action in plan:
            if len(action) == 2:
                print(f"({action[0]} block{action[1]})")
            else:
                print(f"({action[0]} block{action[1]} block{action[2]})")


main()

