blocks = list(range(1, 10))

initial_support = {b: None for b in blocks}
initial_support[2] = 7
initial_support[9] = 2
initial_support[1] = 9
initial_support[4] = 1
initial_support[6] = 4
initial_support[5] = 6
initial_support[3] = 5
initial_support[8] = 3

goal_on_top = {
    9: 8,
    4: 2,
    3: 4,
    7: 3,
    5: 1,
}


def solve(blocks, initial_support, goal_on_top, valid_stack=None):
    if valid_stack is None:
        valid_stack = lambda x, y: True

    support = {b: None for b in blocks}
    support.update(initial_support)

    above = {b: None for b in blocks}
    for b, s in support.items():
        if s is not None:
            above[s] = b

    arm = None
    actions = []

    def is_clear(b):
        return b != arm and above[b] is None

    def do_pickup(b):
        nonlocal arm
        if arm is None and support[b] is None and is_clear(b):
            arm = b
            actions.append(('pickup', b))
            return True
        return False

    def do_putdown(b):
        nonlocal arm
        if arm == b:
            support[b] = None
            arm = None
            actions.append(('putdown', b))
            return True
        return False

    def do_unstack(b, s):
        nonlocal arm
        if arm is None and support[b] == s and is_clear(b):
            arm = b
            support[b] = None
            above[s] = None
            actions.append(('unstack', b, s))
            return True
        return False

    def do_stack(b, s):
        nonlocal arm
        if arm == b and b != s and is_clear(s) and valid_stack(b, s):
            support[b] = s
            above[s] = b
            arm = None
            actions.append(('stack', b, s))
            return True
        return False

    while True:
        moved = False
        for b in blocks:
            if arm is None and support[b] is not None and is_clear(b):
                s = support[b]
                if do_unstack(b, s) and do_putdown(b):
                    moved = True
                    break
        if not moved:
            break

    children = {b: [] for b in blocks}
    for child, parent in goal_on_top.items():
        if child not in children or parent not in children:
            return None
        if not valid_stack(child, parent):
            return None
        children[parent].append(child)

    for b in blocks:
        if len(children[b]) > 1:
            return None

    roots = [b for b in blocks if b not in goal_on_top]
    seen = set(roots)
    goal_stacks = []

    for r in roots:
        cur = r
        st = [r]
        while children.get(cur):
            nxt = children[cur][0]
            if nxt in seen:
                return None
            seen.add(nxt)
            st.append(nxt)
            cur = nxt
        goal_stacks.append(st)

    if len(seen) != len(blocks):
        return None

    for st in goal_stacks:
        for i in range(1, len(st)):
            child = st[i]
            parent = st[i - 1]
            if support[child] is not None or not is_clear(child):
                return None
            if not do_pickup(child):
                return None
            if not do_stack(child, parent):
                return None

    if arm is not None:
        return None

    for b in blocks:
        if support[b] != goal_on_top.get(b, None):
            return None

    return actions


def print_plan(plan):
    if plan is None:
        print("No plan")
    else:
        for action in plan:
            if len(action) == 2:
                print(f"({action[0]} block{action[1]})")
            else:
                print(f"({action[0]} block{action[1]} block{action[2]})")


