    start = (0, tuple(sup), (), 0)
    if is_goal(start):
        return []

    parent = {start: None}
    g = {start: 0}
    heap = [(h(start[1], 0), 0, 0, start)]
    counter = 1

    while heap:
        _, cur_g, _, st = heapq.heappop(heap)
        if cur_g != g[st]:
