    if hand != 0:
        return False
    for b in B:
        if s[b] != goal[b]:
            return False
    return True

def gen(st):
    hand, s, locked, par = st
    ls = set(locked)
    out = []

    def add(act, nh, ns, nl, np):
        out.append((h(ns, nh), act, (nh, tuple(ns), nl, np)))

    if hand == 0:
        for b in B:
            if b in ls:
                continue
            if not is_clear(s, b):
                continue
            if PARITY and par == 1 and b % 4 != 0:
                continue
            ns = list(s)
            ns[b] = 0
            np = 1 - par if PARITY else 0
            if s[b] == 0:
                add(('pickup', b), b, ns, locked, np)
            else:
                add(('unstack', b, s[b]), b, ns, locked, np)
    else:
        b = hand
        if PARITY and par == 1 and b % 4 != 0:
            return []
        np = 1 - par if PARITY else 0

        ns = list(s)
        ns[b] = 0
        nl = tuple(sorted(ls | {b})) if LOCK else locked
        add(('putdown', b), 0, ns, nl, np)

        for y in B:
            if y == b:
                continue
            if not is_clear(s, y):
                continue
            if FRAGILE is not None and y == FRAGILE:
                continue
            ns = list(s)
            ns[b] = y
            add(('stack', b, y), 0, ns, locked, np)

    out.sort(key=lambda x: x[0])
    return [(a, ns) for _, a, ns in out]

def solve():
    start = (0, tuple(sup), (), 0)
    if is_goal(start):
        return []

    parent = {start: None}
    g = {start: 0}
    heap = [(h(start[1], 0), 0, 0, start)]
    counter = 1

    while heap:
        _, cur_g, _, st = heapq.heappop(heap)
        if cur_g != g[st]:
            continue

        if is_goal(st):
            plan = []
            while parent[st] is not None:
                prev, act = parent[st]
                plan.append(act)
                st = prev
            plan.reverse()
            return plan

        for act, ns in gen(st):
            ng = cur_g + 1
            if ng < g.get(ns, 10**9):
                g[ns] = ng
                parent[ns] = (st, act)
                counter += 1
                heapq.heappush(heap, (ng + h(ns[1], ns[0]), ng, counter, ns))

    return None

