        for x in blocks:
            if on.get(x) == b:
                return False
        return True

    for act in actions:
        if act[0] == "pickup":
            if len(act) != 2:
                return False
            b = act[1]
            if b not in on:
                return False
            if arm is not None:
                return False
            if on.get(b) != "table":
                return False
            if not is_clear(b):
                return False
            arm = b
            on[b] = None
        elif act[0] == "putdown":
            if len(act) != 2:
                return False
            b = act[1]
            if b not in on:
                return False
            if arm != b:
                return False
            if on.get(b) is not None:
                return False
            on[b] = "table"
            arm = None
        elif act[0] == "unstack":
            if len(act) != 3:
                return False
            b, sup = act[1], act[2]
            if b not in on or sup not in on:
                return False
            if arm is not None:
                return False
            if on.get(b) != sup:
                return False
            if not is_clear(b):
                return False
            arm = b
            on[b] = None
        elif act[0] == "stack":
            if len(act) != 3:
                return False
            b, sup = act[1], act[2]
            if b not in on or sup not in on:
                return False
            if arm != b:
                return False
            if on.get(b) is not None:
                return False
            if on.get(sup) is None:
                return False
            if not is_clear(sup):
                return False
            on[b] = sup
            arm = None
        else:
