def make_plan(blocks, initial_loc, goal_loc, constraint=None):
    child = {}
    for b in blocks:
        s = goal_loc[b]
        if s != 'table' and s not in blocks:
            return None
        if s != 'table':
            child.setdefault(s, []).append(b)

    for ch in child.values():
        if len(ch) > 1:
            return None

    for b in blocks:
        seen = set()
        cur = b
        while cur != 'table':
            if cur in seen:
                return None
            seen.add(cur)
            cur = goal_loc[cur]

    loc = dict(initial_loc)
    on = {b: None for b in blocks}
    for b in blocks:
        s = loc[b]
        if s != 'table':
            if s not in blocks or on[s] is not None:
                return None
            on[s] = b

    actions = []

    while True:
        top = None
        for b in blocks:
            if loc[b] != 'table' and loc[b] is not None and on[b] is None:
                top = b
                break
        if top is None:
            break

        support = loc[top]
        actions.append(('unstack', top, support))
        loc[top] = None
        on[support] = None

        actions.append(('putdown', top))
        loc[top] = 'table'

    def visit(node):
        ch = child.get(node, [])
        if len(ch) > 1:
            return False
        for c in ch:
            if loc[c] != 'table' or on[c] is not None or on[node] is not None:
                return False
            actions.append(('pickup', c))
            loc[c] = None
            actions.append(('stack', c, node))
            loc[c] = node
            on[node] = c
            if not visit(c):
                return False
        return True

    for r in blocks:
        if goal_loc[r] == 'table':
            if loc[r] != 'table' or on[r] is not None:
                return None
            if not visit(r):
                return None

    if any(loc[b] != goal_loc[b] for b in blocks):
        return None

    loc2 = dict(initial_loc)
    on2 = {b: None for b in blocks}
    held = None
    stacked = set()

    for action in actions:
        a = action[0]
        if a == 'pickup':
            b = action[1]
            if held is not None or loc2[b] != 'table' or on2[b] is not None:
                return None
            held = b
            loc2[b] = None
        elif a == 'unstack':
            b, c = action[1], action[2]
            if held is not None or loc2[b] != c or on2[b] is not None:
                return None
            if constraint == 'no_unstack_after_stack' and b in stacked:
                return None
            held = b
            loc2[b] = None
            on2[c] = None
        elif a == 'putdown':
            b = action[1]
            if held != b:
                return None
            held = None
            loc2[b] = 'table'
        elif a == 'stack':
            b, c = action[1], action[2]
            if held != b or loc2[c] is None or on2[c] is not None or c == b:
                return None
            held = None
            loc2[b] = c
            on2[c] = b
            stacked.add(b)
        else:
            return None

    if held is not None or any(loc2[b] != goal_loc[b] for b in blocks):
        return None

    return actions


