def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

def ordered(stack):
    return all(a < b for a, b in zip(stack, stack[1:]))

def additional_constraints_hold(stacks):
    if len(stacks) != 2:
        return False
    if {b for s in stacks for b in s} != set(range(1, 16)):
        return False
    if not all(ordered(s) for s in stacks):
        return False
    kinds = []
    for s in stacks:
        if all(is_prime(x) for x in s):
            kinds.append("prime")
        elif all(not is_prime(x) for x in s):
            kinds.append("nonprime")
        else:
            return False
    return sorted(kinds) == ["nonprime", "prime"]

