def bname(i):
    return f"block{i}"

def is_legal(support, blocks):
    if set(support) != set(blocks):
        return False
    for b, s in support.items():
        if s == "table":
            continue
        if s not in blocks or s == b:
            return False
    top = {b: None for b in blocks}
    for b, s in support.items():
        if s != "table":
            if top[s] is not None:
                return False
            top[s] = b
    for b in blocks:
        seen = set()
        cur = b
        while cur != "table":
            if cur in seen:
                return False
            seen.add(cur)
            cur = support[cur]
    return True

def top_of(support, blocks):
    top = {b: None for b in blocks}
    for b, s in support.items():
        if s != "table":
            top[s] = b
    return top

def stacks_from(support, blocks):
    stacks = []
    for b in blocks:
        if support[b] == "table":
            stack = [b]
            cur = b
            while True:
                nxt = None
                for x in blocks:
                    if support[x] == cur:
                        nxt = x
                        break
                if nxt is None:
                    break
                stack.append(nxt)
                cur = nxt
            stacks.append(stack)
    return stacks

def make_plan(initial_support, target_support, blocks):
    if not is_legal(initial_support, blocks) or not is_legal(target_support, blocks):
        return None
    support = dict(initial_support)
    top = top_of(support, blocks)
    plan = []
    while True:
        b = None
        for cand in blocks:
            if support[cand] != "table" and top[cand] is None:
                b = cand
                break
        if b is None:
            break
        s = support[b]
        plan.append(("unstack", b, s))
        support[b] = "table"
        top[s] = None
        plan.append(("putdown", b))
    for stack in stacks_from(target_support, blocks):
        for i, b in enumerate(stack):
            if i > 0:
                plan.append(("pickup", b))
                plan.append(("stack", b, stack[i - 1]))
    return plan

def fmt(action):
    return "(" + action[0] + " " + " ".join(bname(x) for x in action[1:]) + ")"

def output(plan):
    if plan is None:
        print("No plan")
    else:
        print("\n".join(fmt(a) for a in plan))

